  window.visW193P=visW193P;
  function visW193Act(lk,act){
    const st=CHS[lk]||(CHS[lk]={});
    if(act==='go'){ if(st.go!=null) st.go++; else st.go=1; }
    if(act==='n'){ st.tr=(st.tr||0)+1; st.go=0; st.pick=null; }
    if(act==='nq'){ st.q=1; st.sel=null; }
    if(act==='rst') CHS[lk]={};
    chRender(0);
  }
