    let s=`<path d="M ${p0.x.toFixed(1)} ${p0.y.toFixed(1)} A ${r} ${r} 0 ${large} 1 ${p1.x.toFixed(1)} ${p1.y.toFixed(1)}" fill="none" stroke="${c}" stroke-width="${opt.w||2.4}"${opt.dash?' stroke-dasharray="6 5"':''}${opt.cls?` class="${opt.cls}"`:''}/>`;
