      const retry= st.pick!=null&&st.pick!==0? `<div class="wk-row" style="gap:8px">${ord.map((o,i)=>`<button class="wk-btn" onclick="visW385P('${lk}',${i})">${o}</button>`).join('')}</div>`:'';
